import org.eclipse.rdf4j.query.algebra.evaluation.util.QueryEvaluationUtility.QueryModelPreparation;
import org.junit.jupiter.api.Test;

class PreparedSafetyAnalysisTest {

	@Test
	void preparedPhasesOnlyAnalyzeSafetyWhenRequested() {
		CountingSingletonSet root = new CountingSingletonSet();

		QueryEvaluationUtility.withPreparedQuerySafetySnapshot(root, IdentityPreparation::new, prepared -> {
			assertThat(root.visits.get()).as("opening a preparation scope must not classify unused safety facts")
					.isZero();
			QueryEvaluationUtility.withFreshPreparedQuerySafetySnapshot(prepared, fresh -> {
				assertThat(root.visits.get()).as("an optimizer without safety queries must not analyze the tree")
						.isZero();
				return fresh;
			});
			assertThat(QueryEvaluationUtility.isRepeatable(prepared)).isTrue();
			assertThat(root.visits.get()).isEqualTo(1);
			assertThat(QueryEvaluationUtility.isRepeatable(prepared)).isTrue();
			assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(prepared)).isFalse();
			assertThat(QueryEvaluationUtility.usesMappingParameterizedEvaluation(prepared)).isFalse();
			assertThat(QueryEvaluationUtility.permitsBindingInjection(prepared, Set.of("outside"))).isTrue();
			assertThat(root.visits.get()).as("subsequent safety queries must reuse the same phase facts")
					.isEqualTo(1);
			return prepared;
		});
	}

	@Test
	void freshPhasesRecomputeSafetyAfterAnEarlierOptimizerRewritesTheTree() {
		QueryRoot root = new QueryRoot(new SingletonSet());
		QueryEvaluationUtility.withPreparedQuerySafetySnapshot(root, IdentityPreparation::new, prepared -> {
			QueryEvaluationUtility.withFreshPreparedQuerySafetySnapshot(prepared, first -> {
				assertThat(QueryEvaluationUtility.isRepeatable(first)).isTrue();
				root.setArg(service());
				return first;
			});
			return QueryEvaluationUtility.withFreshPreparedQuerySafetySnapshot(prepared, second -> {
				assertThat(QueryEvaluationUtility.isRepeatable(second)).isFalse();
				assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(second)).isTrue();
				assertThat(QueryEvaluationUtility.usesMappingParameterizedEvaluation(second)).isTrue();
				return second;
			});
		});
	}

	@Test
	void refreshingBeforeTheFirstSafetyQueryIncludesUnvisitedAncestorsAndSiblings() {
		Extension sibling = new Extension(new SingletonSet(), new ExtensionElem(new BNodeGenerator(), "fresh"));
		Join join = new Join(new SingletonSet(), sibling);
		QueryRoot root = new QueryRoot(join);
		QueryEvaluationUtility.withPreparedQuerySafetySnapshot(root, IdentityPreparation::new, prepared -> {
			join.setLeftArg(new SingletonSet());
			QueryEvaluationUtility.refreshQuerySafetySnapshot(join.getLeftArg());
			assertThat(QueryEvaluationUtility.isRepeatable(prepared)).isFalse();
			assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(prepared)).isFalse();
			assertThat(QueryEvaluationUtility.usesMappingParameterizedEvaluation(prepared)).isFalse();
			assertThat(QueryEvaluationUtility.permitsBindingInjection(join, Set.of("fresh"))).isFalse();
			assertThat(QueryEvaluationUtility.permitsBindingInjection(join, Set.of("outside"))).isTrue();
			return prepared;
		});
	}

	@Test
	void nestedFreshPhasesRestoreTheOuterSafetyFacts() {
		CountingSingletonSet outer = new CountingSingletonSet();
		QueryRoot nested = new QueryRoot(service());
		QueryEvaluationUtility.withPreparedQuerySafetySnapshot(outer, QueryExecutionPolicy.DEFAULT,
				IdentityPreparation::new, prepared -> {
					assertThat(QueryEvaluationUtility.isRepeatable(prepared)).isTrue();
					assertThat(QueryEvaluationUtility.querySafetySnapshot(new SingletonSet()).getQueryExecutionPolicy())
							.isSameAs(QueryExecutionPolicy.DEFAULT);
					QueryEvaluationUtility.withFreshPreparedQuerySafetySnapshot(nested, fresh -> {
						assertThat(QueryEvaluationUtility.isRepeatable(fresh)).isFalse();
						assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(fresh)).isTrue();
						assertThat(QueryEvaluationUtility.querySafetySnapshot(new SingletonSet())
								.getQueryExecutionPolicy())
										.isSameAs(QueryExecutionPolicy.DEFAULT);
						return fresh;
					});
					assertThat(QueryEvaluationUtility.isRepeatable(prepared)).isTrue();
					assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(prepared)).isFalse();
					assertThat(outer.visits.get()).as("the restored outer scope must retain its existing facts")
							.isEqualTo(1);
					return prepared;
				});
	}

	@Test
	void publicSnapshotsCaptureSafetyBeforeSubsequentTreeMutation() {
		QueryRoot root = new QueryRoot(new SingletonSet());
		QueryEvaluationUtility.QuerySafetySnapshot snapshot = QueryEvaluationUtility.querySafetySnapshot(root);
		root.setArg(service());

		assertThat(snapshot.isRepeatable(root)).isTrue();
		assertThat(snapshot.mayRaiseQueryFatalError(root)).isFalse();
		assertThat(QueryEvaluationUtility.querySafetySnapshot(root).isRepeatable(root)).isFalse();
		assertThat(QueryEvaluationUtility.querySafetySnapshot(root).mayRaiseQueryFatalError(root)).isTrue();
	}

	@Test
	void exceptionalFreshPhasesRestoreTheOuterScopeAndCloseInvocationPreparation() {
		CountingSingletonSet outer = new CountingSingletonSet();
		IdentityPreparation preparation = new IdentityPreparation();
		RuntimeException failure = new IllegalStateException("optimizer failed");
		assertThatThrownBy(() -> QueryEvaluationUtility.withPreparedQuerySafetySnapshot(outer,
				QueryExecutionPolicy.DEFAULT, () -> preparation, prepared -> {
					assertThat(QueryEvaluationUtility.isRepeatable(prepared)).isTrue();
					assertThatThrownBy(() -> QueryEvaluationUtility.withFreshPreparedQuerySafetySnapshot(
							new QueryRoot(service()), fresh -> {
								assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(fresh)).isTrue();
								throw failure;
							})).isSameAs(failure);
					assertThat(QueryEvaluationUtility.isRepeatable(prepared)).isTrue();
					assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(prepared)).isFalse();
					assertThat(outer.visits.get()).isEqualTo(1);
					assertThat(preparation.closed).isFalse();
					throw failure;
				})).isSameAs(failure);
		assertThat(preparation.closed).isTrue();
		assertThat(QueryEvaluationUtility.querySafetySnapshot(new SingletonSet()).getQueryExecutionPolicy())
				.isSameAs(QueryExecutionPolicy.EXPERIMENTAL);
	}

	private static Service service() {
		return new Service(Var.of("endpoint"), new SingletonSet(), "", Map.of(), null, false);
	}

	private static final class CountingSingletonSet extends SingletonSet {
		private final AtomicInteger visits = new AtomicInteger();

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visits.incrementAndGet();
			super.visit(visitor);
		}
	}

	/** Separates safety walks from VALUES/graph preparation, whose behavior has its own integration coverage. */
	private static final class IdentityPreparation implements QueryModelPreparation {
		private boolean closed;

		@Override
		public QueryModelNode prepare(QueryModelNode root) {
			return root;
		}

		@Override
		public void resetTraversal() {
		}

		@Override
		public void invalidate(QueryModelNode changedNode) {
		}

		@Override
		public void close() {
			closed = true;
		}
	}
}
